// Host-compiled unit test, no ESP-IDF/hardware dependency.
// Build/run: gcc -I.. test_gfx.c ../gfx.c -o test_gfx && ./test_gfx
//
// Shape-primitive expected coordinate sets below were generated by running the actual
// shared/gfx.py GFX class (not hand-derived) with a pixel-callback recorder, for the exact
// same inputs used here -- see docs/REFACTOR-PLAN.md Phase 7 step 17. Regenerate with:
//
//   python3 -c "
//   import sys, types, builtins
//   builtins.ptr8 = builtins.ptr16 = builtins.ptr32 = object
//   builtins.micropython = types.SimpleNamespace(viper=lambda f: f, native=lambda f: f)
//   sys.path.insert(0, 'shared')
//   import gfx
//   pts = []
//   g = gfx.GFX(32, 32, lambda x, y, *a, **k: pts.append((int(x), int(y))))
//   g.<method>(<args>)
//   print(sorted(set(pts)))
//   "
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "../display/gfx.h"

#define W 32
#define H 32
#define FB_BYTES (W * H / 8)

typedef struct {
    int x, y;
} pt_t;

static int pt_cmp(const void *a, const void *b)
{
    const pt_t *pa = a;
    const pt_t *pb = b;
    if (pa->x != pb->x) {
        return pa->x - pb->x;
    }
    return pa->y - pb->y;
}

static int collect_set_pixels(const uint8_t *fb, pt_t *out, int max_out)
{
    int n = 0;
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            int idx = (y * W + x) >> 3;
            int shift = x & 7;
            if (fb[idx] & (1 << shift)) {
                assert(n < max_out);
                out[n].x = x;
                out[n].y = y;
                n++;
            }
        }
    }
    qsort(out, (size_t)n, sizeof(pt_t), pt_cmp);
    return n;
}

static void check_shape(const char *name, void (*draw)(uint8_t *fb), const pt_t *expected,
                        int n_expected)
{
    uint8_t fb[FB_BYTES];
    memset(fb, 0, sizeof(fb));
    draw(fb);

    pt_t actual[4096];
    int n_actual = collect_set_pixels(fb, actual, 4096);

    if (n_actual != n_expected) {
        fprintf(stderr, "%s: pixel count mismatch: got %d, expected %d\n", name, n_actual,
                n_expected);
        assert(0);
    }
    for (int i = 0; i < n_expected; i++) {
        if (actual[i].x != expected[i].x || actual[i].y != expected[i].y) {
            fprintf(stderr, "%s: mismatch at index %d: got (%d,%d), expected (%d,%d)\n", name, i,
                    actual[i].x, actual[i].y, expected[i].x, expected[i].y);
            assert(0);
        }
    }
}

// clang-format off
static void draw_rect(uint8_t *fb)             { gfx_rect(fb, W, H, 0, 0, 3, 3, 8, 6, 1); }
static void draw_circle(uint8_t *fb)           { gfx_circle(fb, W, H, 0, 0, 15, 15, 5, 1); }
static void draw_fill_circle(uint8_t *fb)      { gfx_fill_circle(fb, W, H, 0, 0, 15, 15, 4, 1); }
static void draw_line(uint8_t *fb)             { gfx_line(fb, W, H, 0, 0, 2, 2, 12, 6, 1); }
static void draw_line_steep(uint8_t *fb)       { gfx_line(fb, W, H, 0, 0, 2, 2, 6, 14, 1); }
static void draw_triangle(uint8_t *fb)         { gfx_triangle(fb, W, H, 0, 0, 2, 2, 14, 4, 6, 12, 1); }
static void draw_fill_triangle(uint8_t *fb)    { gfx_fill_triangle(fb, W, H, 0, 0, 2, 10, 14, 2, 8, 15, 1); }
static void draw_fill_triangle_neg(uint8_t *fb){ gfx_fill_triangle(fb, W, H, 0, 0, 12, 2, 2, 9, 15, 12, 1); }
static void draw_fill_triangle_flat(uint8_t *fb){ gfx_fill_triangle(fb, W, H, 0, 0, 2, 5, 10, 5, 6, 12, 1); }
static void draw_round_rect(uint8_t *fb)       { gfx_round_rect(fb, W, H, 0, 0, 2, 2, 14, 10, 3, 1); }
static void draw_fill_round_rect(uint8_t *fb)  { gfx_fill_round_rect(fb, W, H, 0, 0, 2, 2, 14, 10, 3, 1); }
// clang-format on

