static int mono_bit(const uint8_t *fb, int w, int x, int y)
{
    int idx = (y * w + x) >> 3;
    int shift = x & 7;
    return (fb[idx] >> shift) & 1;
}

static int gs4_nibble(const uint8_t *fb, int w, int x, int y)
{
    int byte_index = y * (w / 2) + (x >> 1);
    int shift = (x & 1) * 4;
    return (fb[byte_index] >> shift) & 0x0F;
}

// gfx_set_pixel's rotation remap, hand-computed against write_pixel_viper's original
// formula (boards/inkplate10/inkplate10.py) for a small 8x4 canvas.
static void test_set_pixel_rotation(void)
{
    uint8_t fb[4];

    // rotation 0: (3,1) -> px=3,py=1 -> idx=1, bit3.
    memset(fb, 0, sizeof(fb));
    gfx_set_pixel(fb, 8, 4, 0, 0, 3, 1, 1);
    assert(fb[1] == 0x08);

    // rotation 1 (90 CW): logical (1,5) -> px=y=5, py=h-1-x=4-1-1=2 -> idx=2, bit5.
    memset(fb, 0, sizeof(fb));
    gfx_set_pixel(fb, 8, 4, 1, 0, 1, 5, 1);
    assert(fb[2] == 0x20);

    // rotation 2 (180): logical (0,0) -> px=w-1-x=7, py=h-1-y=3 -> idx=3, bit7.
    memset(fb, 0, sizeof(fb));
    gfx_set_pixel(fb, 8, 4, 2, 0, 0, 0, 1);
    assert(fb[3] == 0x80);

    // rotation 3 (270 CCW): logical (0,0) -> px=w-1-y=7, py=x=0 -> idx=0, bit7.
    memset(fb, 0, sizeof(fb));
    gfx_set_pixel(fb, 8, 4, 3, 0, 0, 0, 1);
    assert(fb[0] == 0x80);

    // Out-of-bounds is a silent no-op, not a crash/corruption.
    memset(fb, 0, sizeof(fb));
    gfx_set_pixel(fb, 8, 4, 0, 0, 8, 0, 1);
    gfx_set_pixel(fb, 8, 4, 0, 0, -1, 0, 1);
    for (size_t i = 0; i < sizeof(fb); i++) {
        assert(fb[i] == 0);
    }
}

// GS4_HMSB packing: even x -> low nibble, odd x -> high nibble (docs/REFACTOR-PLAN.md
// Phase 5 step 15's fix), raw level 0-7 (not the old 2bpp 0-3 clamp).
static void test_set_pixel_gs4_packing(void)
{
    uint8_t fb[8];
    memset(fb, 0, sizeof(fb));
    gfx_set_pixel(fb, 8, 2, 0, 1, 0, 0, 5); // even x -> low nibble
    gfx_set_pixel(fb, 8, 2, 0, 1, 1, 0, 6); // odd x -> high nibble
    assert(fb[0] == 0x65);
    assert(gs4_nibble(fb, 8, 0, 0) == 5);
    assert(gs4_nibble(fb, 8, 1, 0) == 6);

    // Raw value is masked to 3 bits, not clamped to the old 0-3 range.
    memset(fb, 0, sizeof(fb));
    gfx_set_pixel(fb, 8, 2, 0, 1, 2, 0, 15);
    assert(gs4_nibble(fb, 8, 2, 0) == 7);
}

// Hand-built 4x3 glyph (row_bytes = ceil(4/8) = 1 byte/row, MSB-first per row, matching
// shared/gfx_standard_font_01.py-style get_ch() output):
//   row0: 1010   row1: 0110   row2: 1111
static const uint8_t glyph_4x3[3] = {0xA0, 0x60, 0xF0};

// Replaces gfx.py's separate _draw_char_1bpp/_draw_char_2bpp test coverage -- this is the
// fix for the found bug where text drawn in GS mode still packed 2bpp/0-3 into a buffer
// that's been 4bpp/0-7 (GS4_HMSB) since Phase 5 step 14.
static void test_draw_char_mono(void)
{
    uint8_t fb[FB_BYTES];
    memset(fb, 0, sizeof(fb));
    gfx_draw_char(fb, W, H, 0, 0, 0, 0, glyph_4x3, 4, 3, 1, 1);

    static const pt_t expected[] = {
        {0, 0}, {0, 2}, {1, 1}, {1, 2}, {2, 0}, {2, 1}, {2, 2}, {3, 2},
    };
    pt_t actual[16];
    int n = collect_set_pixels(fb, actual, 16);
    assert(n == (int)(sizeof(expected) / sizeof(expected[0])));
    for (int i = 0; i < n; i++) {
        assert(actual[i].x == expected[i].x && actual[i].y == expected[i].y);
    }
}

static void test_draw_char_scaled(void)
{
    uint8_t fb[FB_BYTES];
    memset(fb, 0, sizeof(fb));
    gfx_draw_char(fb, W, H, 0, 0, 0, 0, glyph_4x3, 4, 3, 2, 1);

    // Glyph (0,0) is on -> the 2x2 block at (0,0)-(1,1) should all be set.
    assert(mono_bit(fb, W, 0, 0) == 1);
    assert(mono_bit(fb, W, 1, 0) == 1);
    assert(mono_bit(fb, W, 0, 1) == 1);
    assert(mono_bit(fb, W, 1, 1) == 1);
    // Glyph (1,0) is off -> its 2x2 block stays clear.
    assert(mono_bit(fb, W, 2, 0) == 0);
    assert(mono_bit(fb, W, 3, 0) == 0);
    assert(mono_bit(fb, W, 2, 1) == 0);
    assert(mono_bit(fb, W, 3, 1) == 0);
}

static void test_draw_char_gs4(void)
{
    uint8_t fb[12]; // phys_w=8 (4 bytes/row) x phys_h=3 -> 12 bytes
    memset(fb, 0, sizeof(fb));
    gfx_draw_char(fb, 8, 3, 0, 1, 0, 0, glyph_4x3, 4, 3, 1, 5);

    // Row 0 glyph bits: col0=1, col2=1 -> raw level 5 at x=0 and x=2, untouched elsewhere.
    assert(gs4_nibble(fb, 8, 0, 0) == 5);
    assert(gs4_nibble(fb, 8, 1, 0) == 0);
    assert(gs4_nibble(fb, 8, 2, 0) == 5);
    assert(gs4_nibble(fb, 8, 3, 0) == 0);
}

int main(void)
{
    test_shapes_vs_python_reference();
    test_set_pixel_rotation();
    test_set_pixel_gs4_packing();
    test_draw_char_mono();
    test_draw_char_scaled();
    test_draw_char_gs4();
    printf("test_gfx: all tests passed\n");
    return 0;
}
